<?php
require_once __DIR__ . '/../includes/bootstrap.php';$user=require_login('seeker');$pdo=database();$s=$pdo->prepare('SELECT js.*,u.email FROM job_seekers js JOIN users u ON u.id=js.user_id WHERE js.user_id=?');$s->execute([$user['id']]);$p=$s->fetch();$sections=['Education'=>'SELECT institution,degree,field_of_study,start_date,end_date,result_gpa FROM education WHERE seeker_id=?','Experience'=>'SELECT company,position_title,description,start_date,end_date FROM experience WHERE seeker_id=?','Projects'=>'SELECT title,description,technologies,project_url FROM projects WHERE seeker_id=?','Skills'=>'SELECT skill_name,skill_level FROM job_seeker_skills WHERE seeker_id=?','Certifications'=>'SELECT certification_name,issuing_organization,issue_date FROM certifications WHERE seeker_id=?','Languages'=>'SELECT language_name,proficiency FROM languages WHERE seeker_id=?']; page_header('CV preview'); ?>
<p><button onclick="window.print()">Print / Save as PDF</button></p><article class="cv"><h1><?=e($p['full_name'])?></h1><p><?=e($p['email'])?> · <?=e($p['phone'])?> · <?=e($p['address'])?></p><p><?=nl2br(e($p['profile_summary']))?></p><?php foreach($sections as $title=>$sql):$s=$pdo->prepare($sql);$s->execute([$user['id']]);$rows=$s->fetchAll();if($rows):?><h2><?=e($title)?></h2><?php foreach($rows as $row):?><p><?php foreach($row as $value) if($value) echo e($value).' '; ?></p><?php endforeach;endif;endforeach;?></article>
<?php page_footer(); ?>